ruleContent.content:
@js:
result=qfContentEntryV38.call(this,result,baseUrl);
try{
  var _u=String(baseUrl||url||'');
  var _bm=_u.match(/[?&]bookId=([^&]+)/i),_cm=_u.match(/[?&]chapterId=([^&]+)/i);
  if(_bm&&_cm){
    var _bid=decodeURIComponent(_bm[1]),_cid=decodeURIComponent(_cm[1]);
    var _sel='';
    try{_sel=String(source.get('qf_review_provider')||source.get('段评来源')||'')}catch(e){}
    if(/情无|小雨|qw|xiaoyu/i.test(_sel)){
      var _d=qfQwDecorateV1214(this,String(result||''),_bid,_cid,'');
      result=_d.content;
      if(_d.titleBubble)source.put('qf_qw_title_'+_cid,_d.titleBubble);
    }
  }
}catch(e){try{java.log('QW comment decorate: '+e)}catch(_){}}
result;

ruleSearch.bookUrl:
@css::root@all@js:
var html=String(result||"");
var m=html.match(/\bdata-bid\s*=\s*"(\d+)"/i);
var bid=m?m[1]:"";

var name="",author="",intro="";
try{name=String(java.getString("@css:[class*=searchBookName]@text",false)||"");}catch(e0){}
try{author=String(java.getString("@css:[class*=searchBookAuthor]@text",false)||"");}catch(e1){}
try{intro=String(java.getString("@css:[class*=searchBookDesc]@text",false)||"");}catch(e2){}

result=bid
    ? "https://m.qidian.com/book/"+bid+
      "/?qfSearchName="+encodeURIComponent(name)+
      "&qfSearchAuthor="+encodeURIComponent(author)+
      "&qfSearchIntro="+encodeURIComponent(intro)
    : "";
